insert into public.products
  (slug, name, tagline, description, category, price, badge, compatibility, variants, highlights, specs, images, video, sort_order)
values
  ('anx-anaconda', 'ANX ANACONDA', 'ידית שאיבה עמידה לחום ולשחיקה, בירוק ג׳ונגל או בשחור — עם אטם קצף היקפי והדק לשליטה מלאה.', 'ANX ANACONDA היא ידית השאיבה שלנו לניקוי ספות וריפודים. הגוף מיוצר בישראל מחומרים חזקים ועמידים במיוחד לחום ולשחיקה של עבודה יומיומית, עם אטם קצף היקפי סביב פתח השאיבה שנצמד לבד ושומר על ואקום מלא לאורך המשיכה. ההדק מאפשר לשלוט בהתזה תוך כדי עבודה בלי להוריד את היד מהידית, והחיבור המהיר בבסיס מתחבר ומתנתק בלי כלים. הידית מגיעה בשני צבעים: ירוק ג׳ונגל, שקל לאתר באתר עבודה עמוס, ושחור נקי ומקצועי.', 'handles', 850, null, ARRAY['Sabrina — ידית שאיבה לניקוי ספות וריפודים']::text[], '[{"id":"color","label":"צבע","options":["ירוק ג׳ונגל","שחור"]}]'::jsonb, ARRAY['אטם קצף היקפי סביב פתח השאיבה', 'הדק לשליטה בהתזה תוך כדי עבודה', 'חיבור מהיר — מתחבר ומתנתק בלי כלים', 'גוף עמיד לחום ולשחיקה, מיוצר בישראל']::text[], '[{"label":"צבעים","value":"ירוק ג׳ונגל · שחור"},{"label":"ייצור","value":"מיוצר בישראל · עמיד לחום ולשחיקה"},{"label":"אטימה","value":"אטם קצף היקפי"},{"label":"שליטה","value":"הדק התזה מובנה"}]'::jsonb, ARRAY['/products/anx-anaconda/1.webp', '/products/anx-anaconda/2.webp', '/products/anx-anaconda/3.webp', '/products/anx-anaconda/4.webp', '/products/anx-anaconda/5.webp', '/products/anx-anaconda/6.webp', '/products/anx-anaconda/7.webp', '/products/anx-anaconda/8.webp']::text[], '{"webm":"/video/anaconda-demo.webm","mp4":"/video/anaconda-demo.mp4","poster":"/video/anaconda-demo-poster.jpg"}'::jsonb, 0),
  ('anx-anaconda-set', 'סט ANACONDA מלא', 'ידית ANACONDA, צינור הזרקה בתוך צינור שאיבה ומחבר 360° — הכל בערכה אחת.', 'הסט המלא של ANACONDA: ידית השאיבה, צינור הזרקה שעובר בתוך צינור השאיבה, ומחבר מסתובב 360° בין הידית לצינור. צינור אחד במקום שניים מקבילים — פחות סיבוכים מתחת לרגליים ופחות מה לגרור בין חדר לחדר. המחבר המסתובב מאפשר לסובב את הידית לכל כיוון בלי שהצינור יתפתל או ימשוך את היד אחורה, וזה מה שמרגישים אחרי שעה של עבודה רצופה.', 'handles', 1600, 'סט מלא', ARRAY['Sabrina — סט שאיבה והזרקה לניקוי ספות וריפודים']::text[], '[{"id":"color","label":"צבע הידית","options":["ירוק ג׳ונגל","שחור"]}]'::jsonb, ARRAY['ידית ANACONDA כלולה בסט', 'צינור הזרקה עובר בתוך צינור השאיבה', 'מחבר מסתובב 360° לתנועה חופשית של הידית', 'חיבור מהיר — מתחבר ומתנתק בלי כלים']::text[], '[{"label":"כולל","value":"ידית · צינור שאיבה עם צינור הזרקה פנימי · מחבר 360°"},{"label":"צבעי הידית","value":"ירוק ג׳ונגל · שחור"},{"label":"ייצור","value":"מיוצר בישראל · עמיד לחום ולשחיקה"}]'::jsonb, ARRAY['/products/anx-anaconda-set/1.webp', '/products/anx-anaconda-set/2.webp', '/products/anx-anaconda-set/3.webp', '/products/anx-anaconda-set/4.webp']::text[], null, 1),
  ('anx-hose-clips', 'סט קליפסים לצינורות — 6 יחידות', 'מאחדים את צינור השאיבה וצינור ההזרקה לקו אחד — בלי שיתפרקו ויסתבכו.', 'הקליפסים מחברים את צינור השאיבה וצינור ההזרקה לקו אחד לאורך כל המשיכה. במקום שני צינורות שנפרדים באמצע העבודה, נתפסים ברגל של ספה ומסתבכים ביד — קו אחד שנגרר נקי אחריך בין חדר לחדר.

ההבדל מורגש בעיקר בשני מקומות: בזמן העבודה, כשאתה לא עוצר כל כמה דקות כדי להפריד ולסדר, ובסוף — כשגלגול הציוד לוקח פחות זמן כי הכל כבר מאוגד. גם צינור ההזרקה הדק פחות חשוף לדריכה ולמעיכה כשהוא צמוד לצינור השאיבה במקום להסתובב לבד על הרצפה.

הקליפס נפתח בצד: לוחצים אותו על הצינורות ביד, בלי כלים ובלי אזיקונים לחתוך. שש יחידות בסט מאפשרות לפרוס אותם לאורך הצינור — צפוף יותר קרוב לידית, שם התנועה הכי גדולה — ולהזיז אותם בכל רגע.', 'hoses', 279, 'סט 6 יחידות', ARRAY['מאחד צינור שאיבה וצינור הזרקה', 'נסגר ביד — בלי כלים ובלי אזיקונים', 'ניתן להוסיף לסט צינורות קיים']::text[], '[{"id":"quantity","label":"כמות","options":["סט 6 יחידות"]}]'::jsonb, ARRAY['שני צינורות נגררים כקו אחד', 'פחות עצירות באמצע העבודה לסידור הצינורות', 'צינור ההזרקה צמוד ומוגן במקום חופשי על הרצפה', 'נפתח ונסגר ביד, וזז לאורך הצינור בכל רגע']::text[], '[{"label":"כמות בסט","value":"6 יחידות"},{"label":"התקנה","value":"הצמדה ביד, ללא כלים"},{"label":"ייצור","value":"מיוצר בישראל · עמיד לחום ולשחיקה"}]'::jsonb, ARRAY['/products/anx-hose-clips/1.webp', '/products/anx-hose-clips/2.webp', '/products/anx-hose-clips/3.webp', '/products/anx-hose-clips/4.webp']::text[], null, 2),
  ('anx-pro-handle', 'ידית שאיבה ANX PRO', 'ידית הדגל שלנו — חלון שקוף, שאיבה חזקה ואחיזה נוחה לאורך יום עבודה.', 'ידית השאיבה ANX PRO תוכננה מאפס עבור עבודה יומיומית בניקוי ספות וריפודים. הגוף השקוף מאפשר לראות בדיוק מה נשאב ומתי המים יוצאים נקיים, כך שאפשר לדעת מתי הסיום אמיתי. פרופיל השפה מותאם לזווית עבודה טבעית ומקטין עייפות בכף היד, ומעבר האוויר הפנימי עוצב למניעת סתימות גם בשאריות סיבים ושיער.', 'handles', 349, 'הנמכר ביותר', ARRAY['Sabrina — כל הדגמים בחיבור סטנדרטי', 'מכונות אקסטרקציה עם צינור ״1.5', 'מתאים לשימוש עם מתאמי ANX3D לכל חיבור אחר']::text[], '[{"id":"color","label":"צבע גוף","options":["שחור","כחול ANX","שקוף מלא"]},{"id":"connection","label":"סוג חיבור","options":["חיבור מהיר","חיבור מוברג"]},{"id":"width","label":"רוחב שפה","options":["רגיל","רחב"]}]'::jsonb, ARRAY['חלון שקוף לבקרת ניקיון בזמן אמת', 'זרימת אוויר מיטבית ללא נקודות סתימה', 'אחיזה ארגונומית להפחתת עומס על כף היד', 'שפה מוחלקת שאינה משאירה סימנים על הבד']::text[], '[{"label":"חומר","value":"פוליקרבונט מוקשח + ABS"},{"label":"רוחב שאיבה","value":"11 ס״מ"},{"label":"משקל","value":"340 גרם"},{"label":"חיבור","value":"״1.5 סטנדרטי"},{"label":"לחץ עבודה מומלץ","value":"עד 60 בר"},{"label":"אחריות","value":"12 חודשים"}]'::jsonb, ARRAY['/products/anx-pro-handle/1.svg', '/products/anx-pro-handle/2.svg', '/products/anx-pro-handle/3.svg']::text[], null, 3),
  ('anx-mini-handle', 'ידית שאיבה MINI', 'ידית קומפקטית לפינות, מושבי רכב ומקומות צרים.', 'ה-MINI נבנתה בדיוק לאותם מקומות שבהם הידית הרגילה גדולה מדי: פינות ספה, תפרים, מושבי רכב ובין המשענות. למרות הגודל הקטן היא שומרת על אותה עוצמת שאיבה, בזכות ערוץ פנימי צר שמאיץ את זרימת האוויר במקום לחנוק אותה.', 'handles', 289, null, ARRAY['Sabrina — כל הדגמים בחיבור סטנדרטי', 'מתאימה לעבודה עם צינור ANX3D בקוטר ״1.5']::text[], '[{"id":"color","label":"צבע גוף","options":["שחור","כחול ANX"]},{"id":"connection","label":"סוג חיבור","options":["חיבור מהיר","חיבור מוברג"]}]'::jsonb, ARRAY['גישה לפינות ותפרים שלא מגיעים אליהם אחרת', 'שאיבה חזקה למרות מידות קומפקטיות', 'קלה במיוחד — נוחה לעבודה מעל הראש', 'מושלמת לניקוי פנים רכב']::text[], '[{"label":"חומר","value":"פוליקרבונט מוקשח"},{"label":"רוחב שאיבה","value":"6 ס״מ"},{"label":"משקל","value":"210 גרם"},{"label":"חיבור","value":"״1.5 סטנדרטי"},{"label":"אחריות","value":"12 חודשים"}]'::jsonb, ARRAY['/products/anx-mini-handle/1.svg', '/products/anx-mini-handle/2.svg', '/products/anx-mini-handle/3.svg']::text[], null, 4),
  ('anx-crystal-handle', 'ידית שאיבה CRYSTAL VIEW', 'גוף שקוף לחלוטין — שליטה מלאה על מה שיוצא מהריפוד.', 'CRYSTAL VIEW היא הידית לאנשי מקצוע שרוצים להראות ללקוח את התוצאה. הגוף שקוף לכל אורכו, כך שכל טיפת מים מלוכלכת נראית בבירור בדרך לצינור. מעבר לאפקט מול הלקוח, השקיפות המלאה עוזרת לזהות סתימה מתחילה עוד לפני שהיא עוצרת את העבודה.', 'handles', 379, 'חדש', ARRAY['Sabrina — כל הדגמים בחיבור סטנדרטי', 'מכונות אקסטרקציה מקצועיות ״1.5']::text[], '[{"id":"color","label":"גימור","options":["שקוף מלא","שקוף עם מסגרת כחולה"]},{"id":"connection","label":"סוג חיבור","options":["חיבור מהיר","חיבור מוברג"]}]'::jsonb, ARRAY['שקיפות מלאה — הלקוח רואה את התוצאה', 'זיהוי מוקדם של סתימות', 'עמידות גבוהה לשריטות', 'ניקוי פנימי קל בסוף יום עבודה']::text[], '[{"label":"חומר","value":"פוליקרבונט שקוף מוקשח"},{"label":"רוחב שאיבה","value":"10 ס״מ"},{"label":"משקל","value":"325 גרם"},{"label":"חיבור","value":"״1.5 סטנדרטי"},{"label":"אחריות","value":"12 חודשים"}]'::jsonb, ARRAY['/products/anx-crystal-handle/1.svg', '/products/anx-crystal-handle/2.svg', '/products/anx-crystal-handle/3.svg']::text[], null, 5),
  ('anx-hose-3m', 'צינור שאיבה מחוזק 3 מ׳', 'צינור עבודה יומיומי — קל, גמיש ולא מתקפל בסיבוב.', 'צינור השאיבה של ANX3D בנוי משכבה פנימית חלקה שמונעת הצטברות לכלוך ומספירלה מחוזקת ששומרת על הקוטר גם כשמושכים אותו סביב רהיט. אורך 3 מטר הוא נקודת האיזון לעבודה בסלון ממוצע — מספיק טווח בלי עודף שמתגלגל על הרצפה.', 'hoses', 249, null, ARRAY['Sabrina — כל הדגמים', 'תואם לכל ידיות השאיבה של ANX3D']::text[], '[{"id":"length","label":"אורך","options":["3 מטר","5 מטר","8 מטר"]},{"id":"color","label":"צבע","options":["שחור","כחול ANX"]}]'::jsonb, ARRAY['ספירלה מחוזקת שלא נמעכת בסיבוב', 'דופן פנימית חלקה — פחות הצטברות לכלוך', 'גמיש גם בטמפרטורות נמוכות', 'קל למשקל — פחות עומס בגרירה']::text[], '[{"label":"אורך","value":"3 מטר"},{"label":"קוטר פנימי","value":"38 מ״מ (״1.5)"},{"label":"חומר","value":"PVC מחוזק בספירלה"},{"label":"טווח טמפרטורה","value":"5°C עד 70°C"},{"label":"אחריות","value":"12 חודשים"}]'::jsonb, ARRAY['/products/anx-hose-3m/1.svg', '/products/anx-hose-3m/2.svg', '/products/anx-hose-3m/3.svg']::text[], null, 6),
  ('anx-hose-5m', 'צינור שאיבה מחוזק 5 מ׳', 'טווח עבודה ארוך לחללים גדולים ולעבודה בקומות.', 'אותה בנייה של צינור ה-3 מטר, בטווח שמאפשר להשאיר את המכונה במקום אחד ולעבוד על סלון שלם, על מדרגות או מתוך הרכב. מומלץ למי שעובד הרבה בבתים פרטיים או במשרדים.', 'hoses', 329, null, ARRAY['Sabrina — כל הדגמים', 'תואם לכל ידיות השאיבה של ANX3D']::text[], '[{"id":"length","label":"אורך","options":["5 מטר","8 מטר"]},{"id":"color","label":"צבע","options":["שחור","כחול ANX"]}]'::jsonb, ARRAY['טווח עבודה שמונע הזזה של המכונה', 'שמירה על עוצמת שאיבה לכל האורך', 'מתאים לעבודה במדרגות ובקומות', 'ניתן לחבר בהמשכיות עם מתאם ANX3D']::text[], '[{"label":"אורך","value":"5 מטר"},{"label":"קוטר פנימי","value":"38 מ״מ (״1.5)"},{"label":"חומר","value":"PVC מחוזק בספירלה"},{"label":"טווח טמפרטורה","value":"5°C עד 70°C"},{"label":"אחריות","value":"12 חודשים"}]'::jsonb, ARRAY['/products/anx-hose-5m/1.svg', '/products/anx-hose-5m/2.svg', '/products/anx-hose-5m/3.svg']::text[], null, 7),
  ('anx-hose-combo', 'צינור משולב שאיבה + לחץ', 'שני קווים בשרוול אחד — פחות כבלים מתפתלים על הרצפה.', 'הצינור המשולב מאגד את קו הלחץ וקו השאיבה בשרוול אחד מסודר. במקום שני צינורות שנסבכים זה בזה מתחת לספה, נשאר קו עבודה אחד נקי. השרוול החיצוני מגן על קו הלחץ משפשוף ומאריך את חיי הצינור.', 'hoses', 399, 'שדרוג מומלץ', ARRAY['Sabrina — כל הדגמים', 'מתאים לעבודה עם ידיות ANX PRO ו-CRYSTAL VIEW']::text[], '[{"id":"length","label":"אורך","options":["3 מטר","5 מטר"]},{"id":"connection","label":"חיבור לחץ","options":["ניתוק מהיר","מוברג"]}]'::jsonb, ARRAY['קו עבודה אחד במקום שניים', 'שרוול מגן מפני שפשוף ובלאי', 'התחברות מהירה בתחילת יום עבודה', 'פחות סיכון להיתקלות בכבלים בבית הלקוח']::text[], '[{"label":"אורך","value":"3 מטר"},{"label":"קו שאיבה","value":"38 מ״מ (״1.5)"},{"label":"קו לחץ","value":"עד 70 בר"},{"label":"חומר שרוול","value":"ניילון קלוע"},{"label":"אחריות","value":"12 חודשים"}]'::jsonb, ARRAY['/products/anx-hose-combo/1.svg', '/products/anx-hose-combo/2.svg', '/products/anx-hose-combo/3.svg']::text[], null, 8),
  ('anx-adapter-sabrina', 'מתאם Sabrina ↔ ידית', 'המתאם הבסיסי שמחבר כל ידית ANX3D למכונה שלך.', 'מתאם ההתאמה הסטנדרטי בין יציאת ה-Sabrina לכל ידית שאיבה של ANX3D. אטימה כפולה מונעת אובדן ואקום, וזה מורגש ישירות בעוצמת השאיבה. אם זו ההזמנה הראשונה שלך אצלנו — זה החלק שכדאי להוסיף לעגלה.', 'adapters', 89, null, ARRAY['Sabrina — כל הדגמים', 'כל ידיות השאיבה של ANX3D']::text[], '[{"id":"color","label":"צבע","options":["שחור","כחול ANX"]},{"id":"seal","label":"אטימה","options":["O-Ring כפול","O-Ring בודד"]}]'::jsonb, ARRAY['אטימה כפולה — בלי אובדן ואקום', 'מתחבר ומתנתק בלי כלים', 'עמיד לחומרי ניקוי מקצועיים', 'החלק הראשון שכדאי להוסיף לערכה']::text[], '[{"label":"חומר","value":"ABS מוקשח + אטמי NBR"},{"label":"קוטר","value":"38 מ״מ (״1.5)"},{"label":"משקל","value":"75 גרם"},{"label":"אחריות","value":"12 חודשים"}]'::jsonb, ARRAY['/products/anx-adapter-sabrina/1.svg', '/products/anx-adapter-sabrina/2.svg', '/products/anx-adapter-sabrina/3.svg']::text[], null, 9),
  ('anx-adapter-quick', 'מתאם ניתוק מהיר QUICK-LOCK', 'מחליף ידית תוך שנייה, בלי לעצור את המכונה.', 'מנגנון הניתוק המהיר מאפשר להחליף בין ידית רגילה לידית MINI באמצע עבודה, בלי להוריד לחץ ובלי להתעסק בהברגות. נעילה בסיבוב רבע וקליק ברור שמאשר שהחיבור נעול.', 'adapters', 129, 'חוסך זמן', ARRAY['Sabrina — כל הדגמים', 'כל ידיות וצינורות ANX3D']::text[], '[{"id":"color","label":"צבע","options":["שחור","כחול ANX"]},{"id":"kit","label":"תצורה","options":["יחידה בודדת","זוג (זכר + נקבה)"]}]'::jsonb, ARRAY['החלפת אביזר בשנייה אחת', 'נעילת רבע סיבוב עם קליק מאשר', 'מונע נזק להברגות משימוש חוזר', 'מתאים לעבודה עם מספר ידיות ביום']::text[], '[{"label":"חומר","value":"ABS מוקשח + נירוסטה"},{"label":"קוטר","value":"38 מ״מ (״1.5)"},{"label":"מנגנון","value":"נעילת רבע סיבוב"},{"label":"אחריות","value":"12 חודשים"}]'::jsonb, ARRAY['/products/anx-adapter-quick/1.svg', '/products/anx-adapter-quick/2.svg', '/products/anx-adapter-quick/3.svg']::text[], null, 10),
  ('anx-adapter-90', 'מתאם זווית 90°', 'מוריד את גובה העבודה מתחת לרהיטים ובין המשענות.', 'מתאם הזווית מפנה את קו השאיבה בתשעים מעלות ומאפשר להגיע מתחת לספות נמוכות, בין משענות ובתוך רכב, בלי לכופף את פרק כף היד. משתלב עם כל ידיות ANX3D וניתן לשלב אותו עם מתאם ה-QUICK-LOCK.', 'adapters', 79, null, ARRAY['Sabrina — כל הדגמים', 'כל ידיות ANX3D', 'ניתן לשלב עם QUICK-LOCK']::text[], '[{"id":"angle","label":"זווית","options":["90°","45°"]},{"id":"color","label":"צבע","options":["שחור","כחול ANX"]}]'::jsonb, ARRAY['הגעה למקומות נמוכים בלי לכופף את היד', 'מפחית עומס על פרק כף היד', 'ניתן לשלב עם ניתוק מהיר', 'זרימה פנימית מעוגלת שלא חונקת את השאיבה']::text[], '[{"label":"חומר","value":"ABS מוקשח"},{"label":"זווית","value":"90 מעלות"},{"label":"קוטר","value":"38 מ״מ (״1.5)"},{"label":"משקל","value":"85 גרם"},{"label":"אחריות","value":"12 חודשים"}]'::jsonb, ARRAY['/products/anx-adapter-90/1.svg', '/products/anx-adapter-90/2.svg', '/products/anx-adapter-90/3.svg']::text[], null, 11);


