values
  ('course-stain-removal', 'קורס הסרת כתמי השחמות – 1 על 1', 'קורס אונליין אישי 1 על 1 להסרת כתמי השחמות ממזרנים, בלי אבקות.', 'נמאס לכם כל פעם להתאכזב שהחומרים שקניתם לא מביאים לכם תוצאות? אצלנו תמצאו את הפתרון בהמצאות הנוסחה הבלעדית שפיתחנו. קורס 1 על 1 אונליין איתי, שבו אתם מקבלים ידע 100% בהסרת כתמי השחמות ממזרנים — בלי אבקות.', 'courses', 1480, null, ARRAY[]::text[], '[]'::jsonb, ARRAY['ידע מלא (100%) בהסרת כתמי השחמות ממזרנים', 'שיטה בלי אבקות', 'נוסחה בלעדית שפותחה על ידינו', 'קורס אונליין אישי, 1 על 1']::text[], '[{"label":"פורמט","value":"קורס אונליין אישי (1 על 1)"},{"label":"הרשמה","value":"בוואטסאפ"}]'::jsonb, ARRAY['/products/course-stain-removal/1.webp']::text[], '{"webm":"/video/course-stain-removal.webm","mp4":"/video/course-stain-removal.mp4","poster":"/video/course-stain-removal-poster.jpg"}'::jsonb, 12);
